package com.example.jobfinderapp.activities;
import android.content.Intent;import android.os.Bundle;import android.text.TextUtils;import android.util.Patterns;import android.widget.Toast;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import com.bumptech.glide.Glide;import com.example.jobfinderapp.R;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.Company;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;import com.google.android.material.appbar.MaterialToolbar;import com.google.android.material.button.MaterialButton;import com.google.android.material.floatingactionbutton.FloatingActionButton;import com.google.android.material.textfield.TextInputEditText;import de.hdodenhof.circleimageview.CircleImageView;
public class CompanyProfileActivity extends AppCompatActivity{
 private CircleImageView logo;private TextInputEditText name,website,address,desc;private MaterialButton save;private FloatingActionButton pick;private DBHelper db;private int userId;private Company company;private ActivityResultLauncher<String> picker;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_company_profile);db=DBHelper.getInstance(this);UserSession s=new UserSession(this);userId=s.isLoggedIn()?s.getUserId():-1;User u=userId>0?db.getUserById(userId):null;if(u==null||!DBHelper.ROLE_EMPLOYER.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())){s.clear();Intent i=new Intent(this,LoginActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();return;}logo=findViewById(R.id.imgCompanyLogo);name=findViewById(R.id.etCompanyName);website=findViewById(R.id.etCompanyWebsite);address=findViewById(R.id.etCompanyAddress);desc=findViewById(R.id.etCompanyDesc);save=findViewById(R.id.btnUpdateCompany);pick=findViewById(R.id.btnChangeLogo);MaterialToolbar t=findViewById(R.id.toolbar);t.setNavigationOnClickListener(v->finish());picker=registerForActivityResult(new ActivityResultContracts.GetContent(),uri->{if(uri!=null){logo.setImageURI(uri);if(company==null){company=new Company();company.setUserId(userId);}company.setLogo(uri.toString());}});pick.setOnClickListener(v->picker.launch("image/*"));load();save.setOnClickListener(v->update());}
 private void load(){company=db.getCompanyByUserId(userId);if(company==null){company=new Company();company.setUserId(userId);}name.setText(company.getName());website.setText(company.getWebsite());address.setText(company.getAddress());desc.setText(company.getDescription());if(!TextUtils.isEmpty(company.getLogo()))Glide.with(this).load(company.getLogo()).placeholder(R.drawable.bg_header_gradient).error(R.drawable.bg_header_gradient).into(logo);}
 private void update(){String n=name.getText().toString().trim(),w=website.getText().toString().trim(),a=address.getText().toString().trim(),d=desc.getText().toString().trim();if(n.isEmpty()){name.setError("Vui lòng nhập tên công ty");return;}if(a.isEmpty()){address.setError("Vui lòng nhập địa chỉ");return;}if(!w.isEmpty()&&!Patterns.WEB_URL.matcher(w).matches()){website.setError("Website không hợp lệ");return;}if(d.length()>2000){desc.setError("Mô tả quá dài");return;}company.setName(n);company.setWebsite(w);company.setAddress(a);company.setDescription(d);company.setUserId(userId);if(db.upsertCompany(company)){setResult(RESULT_OK);Toast.makeText(this,"Đã cập nhật hồ sơ công ty",Toast.LENGTH_SHORT).show();finish();}else Toast.makeText(this,"Không thể lưu hồ sơ công ty",Toast.LENGTH_SHORT).show();}
}
